#include <iostream>
using namespace std;

int recSum(int n) {
    if (n==1){
    	return 1;
    }
    else{
    	return n+recSum(n-1);
    }
}

int main() {
    int n;
    cin >> n;
    
    cout<<recSum(n);    
    
    return 0;
}
